mapper.select:
select

from PBC_CAP_ASSET_INFO
where ASSETID = #{assetid}
and status =#{status}

select distinct b.ASSET_UUID as assetUuid /*主键*/, t.ASSET_CODE as assetCode/*资产代码*/, t.ASSET_NAME as assetName /*资产名称*/, b.POBCASSETID as pobcassetid/*人行资金信托代码*/, t.PLAN_SDATE as planSdate /*资产起息日*/, t.PLAN_EDATE as planEdate /*资产到期日*/, b.UPDATE_TIME as updateTime from chb_asset_info t left join PBC_CAP_ASSET_INFO b on t.ASSET_CODE = b.ASSETID and b.STATUS!='D' where t.PBC_ASSET_TYPE1='P07' and t.PBC_ASSET_TYPE2='T02' and t.PBC_ASSET_TYPE3='M02' and t.STATUS!='D'
AND DATE_FORMAT(t.PLAN_SDATE,'%Y-%m-%d') >= #{planSdateStart}
AND DATE_FORMAT(t.PLAN_SDATE,'%Y-%m-%d') <= #{planSdateEnd}
AND DATE_FORMAT(t.PLAN_EDATE,'%Y-%m-%d') >= #{planEdateStart}
AND DATE_FORMAT(t.PLAN_EDATE,'%Y-%m-%d') <= #{planEdateEnd}
and b.POBCASSETID in
#{pobcassetid}
and t.ASSET_CODE in
#{assetCode}
order by b.UPDATE_TIME desc

select
t.ASSET_CODE as assetid/*资产代码*/,
t.ASSET_NAME as assetName /*资产名称*/,
b.POBCASSETID as pobcassetid/*人行资金信托代码*/
from chb_asset_info t
left join PBC_CAP_ASSET_INFO b on t.ASSET_CODE = b.ASSETID  and b.STATUS!='D'
where t.PBC_ASSET_TYPE1='P07'
and t.PBC_ASSET_TYPE2='T02'
and t.PBC_ASSET_TYPE3='M02'
and t.STATUS!='D'

    AND DATE_FORMAT(t.PLAN_SDATE,'%Y-%m-%d') >= #{planSdateStart}


    AND DATE_FORMAT(t.PLAN_SDATE,'%Y-%m-%d') <= #{planSdateEnd}


    AND DATE_FORMAT(t.PLAN_EDATE,'%Y-%m-%d') >= #{planEdateStart}


    AND DATE_FORMAT(t.PLAN_EDATE,'%Y-%m-%d') <= #{planEdateEnd}


    and b.POBCASSETID in

        #{pobcassetid}



    and t.ASSET_CODE in

        #{assetCode}



    and b.ASSET_UUID in

        #{item,jdbcType=VARCHAR}


order by b.UPDATE_TIME desc
